      if (jsUrl) settings.jsUrl = jsUrl;
      if (wasmUrl) settings.wasmUrl = wasmUrl;
      basisTranscodedTextureFormat = preferredTranscodedFormat.filter((format) => supportedTextures.includes(format))[0];
